# 0.3.0: каталог и общий редактор миров, защищённый ввод и welcome (#124/#135/#136/#141/#142).
# Старые слои остаются историей. Здесь только согласованный демонстрационный контент.
def release_page(title, body, action, back=True):
    return page(f'''<div style="padding:12px 20px;border-bottom:1px solid #262634;font-weight:700">{'‹　' if back else ''}{title}</div>
    <div style="padding:18px 20px">{body}</div>
    <div style="position:fixed;bottom:0;left:0;right:0;box-sizing:border-box;padding:18px 20px 24px;background:#0E0E13"><button class="btn" style="width:100%;box-sizing:border-box">{action}</button></div>''')

def release_field(label, value):
    return f'<div class="small muted" style="margin:14px 0 8px">{label}</div><div class="card" style="white-space:pre-wrap">{value}</div><span class="chip" style="margin:6px 0">Очистить</span>'

S['01-1_invite'] = release_page('реки', '''<h1 style="font-size:38px;line-height:1.05;letter-spacing:-1px">Твой блог.<br>Твоя история.</h1>
<p class="muted">Пиши посты, знакомься с героями и меняй события своего мира.</p>
<div class="card" style="margin:28px 0 16px;border:1px solid #9B6BFF66;transform:rotate(-1deg)"><b>✦　Твой канал</b><div class="small muted">только что · 120 читателей</div><p>На моей фотографии появилась улица, которой вчера не было. Кто-нибудь узнаёт эти окна? 🌲</p><span class="react">👀 24</span><span class="react">✨ 12</span><span class="small muted">💬 3</span><div style="margin:16px 0 0 12px;padding-left:12px;border-left:2px solid #C3A8FF" class="small"><b>Герой мира</b><div>Я помню этот дом. Но на карте его нет уже сорок лет.</div></div></div>
<p class="small muted">Фанаты и события виртуальные. Посты остаются внутри игры.</p>''', 'Начать играть', False)

catalog = '<h1>Где начнётся твоя история?</h1><p class="muted">Все готовые миры доступны сразу. У каждого — свои герои и темп роста.</p>'
for emoji, title, description in [
    ('🌲', 'Вечерело', 'Дождливый город в Калининградской области. Исчезнувшие улицы, городские тайны и симпатии.'),
    ('✨', 'Школа чародеев', 'Академия на острове в Ладожском озере. Школа меняется каждую ночь, а записи в ленте остаются.'),
    ('👑', 'Игра домов', 'Северное царство. Борьба домов за влияние, союзы, драконы и ледяная Стена.'),
    ('💻', 'Айти-тусовка', 'Стартапы, релизы, рабочие споры и ирония.')]:
    catalog += f'<div class="card" style="margin-bottom:10px"><b>{emoji} {title}</b><div class="small muted">{description}</div></div>'
catalog += '<div class="card"><b>✨ Создать с нуля</b><p class="small muted">Набери 500 подписчиков в любом мире или пригласи друга по своей ссылке. Доступ открывает начисленный бонус за друга.</p></div>'
S['01-3_world'] = page('<div style="padding:12px 20px;border-bottom:1px solid #262634;font-weight:700">‹　Выбери мир</div><div style="padding:18px 20px">' + catalog + '</div>')
S['05-7_new_world'] = S['01-3_world']
