S['01-5_first_star'] = release_page('Герои · 4 / 4', '<h1>Кто живёт в твоём мире?</h1><p class="muted">Настрой состав героев, их характеры и голоса. Это не выбор первой подписки.</p><div class="card"><b>Изабелла Лебедева</b>' + release_field('ИМЯ ГЕРОЯ', 'Изабелла Лебедева') + release_field('РОЛЬ ГЕРОЯ', 'Автор ночных фотографий') + release_field('ХАРАКТЕР И ИСТОРИЯ', 'На её снимках видны отдельные детали чужих воспоминаний. Она проверяет находки по свидетельствам жителей.') + '<div class="small muted">Голос, аватар и главная черта редактируются ниже.</div></div><p class="small muted">Можно добавить и убрать героев. Минимум один AI-герой.</p>', 'Создать мир')
S['05-11_world_rules'] = release_page('Настройки мира', '<h1>🌲 Вечерело</h1><p class="muted">Правила и контент выбранного экземпляра.</p><div class="card">🔒 Без тем 18+ и травли по внешности<br><br>Тайны раскрываются постепенно в общей ленте.</div><h2>Редактировать мир</h2><p class="muted">Пройди настройки канала, описания, голоса и героев. В конце нажми «Сохранить изменения». Подписчики и прогресс сохранятся.</p>', 'Редактировать мир')
